-- =====================================================================
-- MockData_Fixtures_Nexus.sql — Capa de datos del Documento E2 (BancoERP Nexus)
-- Requiere: BD bancoerp_e2_qa con esquema y carga base (MockData_Sintetica.sql).
-- Idempotente: re-ejecutarlo "reinicia el fixture" (saldos, estados, acumulados).
-- Datos 100 % sintéticos: dominios .test / .invalid, DPIs 29999999901xx ficticios.
-- Ejecutar: psql -h 127.0.0.1 -p 15433 -U e2qa -d bancoerp_e2_qa -f MockData_Fixtures_Nexus.sql
-- =====================================================================
\set ON_ERROR_STOP on
DO $$ BEGIN IF current_database() <> 'bancoerp_e2_qa' THEN RAISE EXCEPTION 'Solo bancoerp_e2_qa (QA aislado)'; END IF; END $$;
BEGIN;

