INSERT INTO cuentas.cuentas (id,numero_cuenta,cliente_id,tipo_cuenta,saldo,saldo_disponible,saldo_minimo,limite_retiro_diario,monto_retirado_hoy,estado,moneda) VALUES ('f448814a-3b4e-53e9-a426-f8592316be4d','AH261002000211','29f57303-cfdf-5c62-883f-ac4372522b71','AHORRO','1000.00','1000.00','100.00','5000.00','0.00','ACTIVA','GTQ') ON CONFLICT (id) DO UPDATE SET saldo=EXCLUDED.saldo, saldo_disponible=EXCLUDED.saldo_disponible, saldo_minimo=EXCLUDED.saldo_minimo, limite_retiro_diario=EXCLUDED.limite_retiro_diario, monto_retirado_hoy=EXCLUDED.monto_retirado_hoy, estado=EXCLUDED.estado;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='cuentas' AND table_name='cuentas' AND column_name='saldo_retenido') THEN
    UPDATE cuentas.cuentas SET saldo_retenido=0 WHERE numero_cuenta LIKE 'AH2610020002%' OR numero_cuenta LIKE 'MO2610020002%' OR numero_cuenta LIKE 'AH2610020001%' OR numero_cuenta LIKE 'MO2610020001%';
  END IF;
END $$;

-- 5. Limpieza para re-ejecución: cajas abiertas de los operadores QA y clientes creados por los casos
UPDATE cajas.sesiones_caja SET estado='CERRADA', hora_cierre=now() WHERE estado='ABIERTA' AND cajero_id IN (SELECT e.id FROM rrhh.empleados e JOIN seguridad.usuarios u ON u.id=e.usuario_id WHERE u.username IN ('qa_cajero','qa_cajero2'));
DO $$ BEGIN
  DELETE FROM crm.clientes c WHERE c.dpi IN ('2999999990199','2999999990198','2999999990197','2999999990196','2999999990195') AND NOT EXISTS (SELECT 1 FROM cuentas.cuentas x WHERE x.cliente_id=c.id);
EXCEPTION WHEN foreign_key_violation THEN RAISE NOTICE 'Clientes creados por casos con dependencias; limpiar manualmente si se requiere';
END $$;
COMMIT;

